insert into public.tutor_test_evidence(tutor_id,prepared_by,note) values('00000000-0000-0000-0000-000000000003','00000000-0000-0000-0000-000000000006','SYNTHETIC classroom metadata; not physical verification.');
create function pg_temp.review_token(target uuid) returns text language sql security invoker as $$
  select x->>'token' from jsonb_array_elements(public.load_test_trust_workspace()->'tutor_reviews') x where x->>'tutor_id'=target::text;
$$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","session_id":"00000000-0000-0000-0000-000000000001"}',true);
select pg_temp.assert_true(jsonb_array_length(public.load_test_trust_workspace()->'tutor_reviews')=0,'learner cannot see review queue');
select pg_temp.expect_error($q$select public.review_test_tutor('00000000-0000-0000-0000-000000000003','forged','approved',10::smallint,'Unauthorised approval reason',gen_random_uuid())$q$,'42501','learner cannot approve');
select pg_temp.expect_error($q$insert into public.tutor_test_evidence(tutor_id,prepared_by,note) values('00000000-0000-0000-0000-000000000003',auth.uid(),'forged synthetic metadata')$q$,'42501','browser cannot manufacture evidence');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000005","session_id":"00000000-0000-0000-0000-000000000005"}',true);
select pg_temp.assert_true(jsonb_array_length(public.load_test_trust_workspace()->'tutor_reviews')=2,'Champion sees real test tutor queue');
select pg_temp.assert_true(public.load_test_trust_workspace()::text not like '%example.invalid%' and public.load_test_trust_workspace()::text not like '%Fictional test%','queue excludes email and private names');
create temporary table review_intent as select pg_temp.review_token('00000000-0000-0000-0000-000000000003') token;
select public.review_test_tutor('00000000-0000-0000-0000-000000000003',(select token from review_intent),'approved',10::smallint,'Synthetic classroom requirements reviewed.','81000000-0000-4000-8000-000000000001');
select public.review_test_tutor('00000000-0000-0000-0000-000000000003',(select token from review_intent),'approved',10::smallint,'Synthetic classroom requirements reviewed.','81000000-0000-4000-8000-000000000001');
select pg_temp.assert_true(jsonb_array_length(public.load_test_trust_workspace()->'recent_actions')=1,'replayed approval creates one immutable audit operation');
select pg_temp.expect_error($q$select public.review_test_tutor('00000000-0000-0000-0000-000000000003',(select token from review_intent),'approved',10::smallint,'Changed reason on a reused request.','81000000-0000-4000-8000-000000000001')$q$,'22023','request cannot be reused for altered payload');
select pg_temp.expect_error($q$select public.review_test_tutor('00000000-0000-0000-0000-000000000003',(select token from review_intent),'revoked',null,'Stale revocation must fail.',gen_random_uuid())$q$,'40001','stale decision cannot override current review');
select pg_temp.expect_error($q$select public.review_test_tutor('00000000-0000-0000-0000-000000000008',pg_temp.review_token('00000000-0000-0000-0000-000000000008'),'approved',12::smallint,'Missing metadata cannot be approved.',gen_random_uuid())$q$,'22023','approval requires synthetic metadata and qualifications');
select pg_temp.expect_error($q$select public.review_test_tutor('00000000-0000-0000-0000-000000000003',pg_temp.review_token('00000000-0000-0000-0000-000000000003'),'revoked',null,'short',gen_random_uuid())$q$,'22023','meaningful reason required');
select pg_temp.expect_error($q$select * from public.test_trust_audit$q$,'42501','raw audit payload not exposed to browser');
select pg_temp.assert_true(public.load_test_trust_history('tutor','00000000-0000-0000-0000-000000000003')#>>'{records,0,actor_id}'='00000000-0000-0000-0000-000000000005','reviewer identity is current server actor');
reset role;
update public.tutor_profiles set discovery_preview_enabled=true where user_id='00000000-0000-0000-0000-000000000003';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","session_id":"00000000-0000-0000-0000-000000000001"}',true);
select pg_temp.assert_true(jsonb_array_length(public.discover_test_tutors('cbse-8-mathematics','English')->'candidates')=1,'authorised test approval enables otherwise qualified opted-in candidate');
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000005","session_id":"00000000-0000-0000-0000-000000000005"}',true);
select public.review_test_tutor('00000000-0000-0000-0000-000000000003',pg_temp.review_token('00000000-0000-0000-0000-000000000003'),'revoked',null,'Synthetic classroom approval withdrawn.',gen_random_uuid());
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000001","session_id":"00000000-0000-0000-0000-000000000001"}',true);
select pg_temp.assert_true(jsonb_array_length(public.discover_test_tutors('cbse-8-mathematics','English')->'candidates')=0,'committed revocation immediately excludes candidate on next query');
select pg_temp.expect_error($q$select public.load_test_trust_history('tutor','00000000-0000-0000-0000-000000000003')$q$,'42501','unrelated learner cannot read tutor review evidence');
reset role;
insert into public.user_roles(user_id,role) values('00000000-0000-0000-0000-000000000003','champion');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000003","session_id":"00000000-0000-0000-0000-000000000003"}',true);
select pg_temp.expect_error($q$select public.review_test_tutor(auth.uid(),'any','approved',10::smallint,'Self review is always forbidden.',gen_random_uuid())$q$,'42501','even a multi-role reviewer cannot self-approve');
reset role;
set local role service_role;
select pg_temp.expect_error($q$update public.test_trust_audit set reason='rewritten audit'$q$,'42501','audit immutable even to service API');
select pg_temp.expect_error($q$delete from public.tutor_test_evidence$q$,'42501','synthetic evidence append-only');
reset role;
set local role anon;
select pg_temp.expect_error($q$select public.load_test_trust_workspace()$q$,'42501','anonymous queue access denied');
reset role;
